MSIGX                   = $d010 ; Bit 8 of the X position of each sprite (bit n = sprite n). Used: written 1.
SCROLY                  = $d011 ; Control 1: vertical scroll (bits 0-2), 25/24 rows (bit 3), display enable (bit 4), bitmap mode (bit 5), extended color mode (bit 6), raster line bit 8 (bit 7). Used: written 2.
RASTER                  = $d012 ; Read: raster line bits 0-7. Write: raster interrupt line bits 0-7. Used: written 2.
SPENA                   = $d015 ; Sprite enable (bit n = sprite n). Used: written 2.
SCROLX                  = $d016 ; Control 2: horizontal scroll (bits 0-2), 40/38 columns (bit 3), multicolor mode (bit 4). Used: written 1.
VMCSB                   = $d018 ; Memory setup: character or bitmap base (bits 1-3), screen memory (bits 4-7), inside the VIC-II bank. Used: written 2.
VICIRQ                  = $d019 ; Interrupt flags: raster (bit 0), sprite-background (bit 1), sprite-sprite (bit 2), light pen (bit 3), any (bit 7). Write 1 to clear a flag. Used: read 1, written 1.
IRQMSK                  = $d01a ; Interrupt enable: raster (bit 0), sprite-background (bit 1), sprite-sprite (bit 2), light pen (bit 3). Used: written 1.
SPBGPR                  = $d01b ; Sprite behind the background (bit n = sprite n). Used: written 1.
XXPAND                  = $d01d ; Sprite double width (bit n = sprite n). Used: written 1.
EXTCOL                  = $d020 ; Border color (bits 0-3). Used: written 4.
BGCOL0                  = $d021 ; Background color 0 (bits 0-3). Used: written 2.
BGCOL1                  = $d022 ; Background color 1 (multicolor and extended color modes). Used: written 1.
BGCOL2                  = $d023 ; Background color 2 (multicolor and extended color modes). Used: written 1.
SP0COL                  = $d027 ; Sprite 0 color. Used: written 1.

; SID registers $d400-$d7ff
FRELO1                  = $d400 ; SID voice 1 frequency, low byte. Write only. Used: written 4.
FREHI1                  = $d401 ; SID voice 1 frequency, high byte. Write only. Used: written 1.
VCREG1                  = $d404 ; SID voice 1 control: gate (bit 0), sync (bit 1), ring modulation (bit 2), test (bit 3), waveform triangle/saw/pulse/noise (bits 4-7). Write only. Used: written 5.
SUREL1                  = $d406 ; SID voice 1 sustain (bits 4-7) and release (bits 0-3). Write only. Used: written 2.
FRELO2                  = $d407 ; SID voice 2 frequency, low byte. Write only. Used: written 2.
FREHI2                  = $d408 ; SID voice 2 frequency, high byte. Write only. Used: written 4.
VCREG2                  = $d40b ; SID voice 2 control: gate (bit 0), sync (bit 1), ring modulation (bit 2), test (bit 3), waveform triangle/saw/pulse/noise (bits 4-7). Write only. Used: written 6.
ATDCY2                  = $d40c ; SID voice 2 attack (bits 4-7) and decay (bits 0-3). Write only. Used: written 4.
SUREL2                  = $d40d ; SID voice 2 sustain (bits 4-7) and release (bits 0-3). Write only. Used: written 3.
FRELO3                  = $d40e ; SID voice 3 frequency, low byte. Write only. Used: written 1.
FREHI3                  = $d40f ; SID voice 3 frequency, high byte. Write only. Used: written 3.
VCREG3                  = $d412 ; SID voice 3 control: gate (bit 0), sync (bit 1), ring modulation (bit 2), test (bit 3), waveform triangle/saw/pulse/noise (bits 4-7). Write only. Used: written 7.
ATDCY3                  = $d413 ; SID voice 3 attack (bits 4-7) and decay (bits 0-3). Write only. Used: written 3.
SUREL3                  = $d414 ; SID voice 3 sustain (bits 4-7) and release (bits 0-3). Write only. Used: written 2.
SIGVOL                  = $d418 ; SID volume (bits 0-3) and filter mode (bits 4-7). Write only. Used: written 2.

; CIA 1 registers $dc00-$dcff
CIAPRA                  = $dc00 ; CIA 1: Port A: keyboard columns (write) and joystick 2 (read). Used: read 2, written 3.
CIAPRB                  = $dc01 ; CIA 1: Port B: keyboard rows (read) and joystick 1 (read). Used: read 5.
CIATALO                 = $dc04 ; CIA 1: Timer A, low byte. Used: read 1, written 1.
CIATAHI                 = $dc05 ; CIA 1: Timer A, high byte. Used: read 1, written 1.
CIAICR                  = $dc0d ; CIA 1: Interrupt control: read gives the sources and clears them; write sets (bit 7 = 1) or clears (bit 7 = 0) the enable bits. Its interrupt goes to the IRQ line. Used: written 1.

; CIA 2 registers $dd00-$ddff
CI2TALO                 = $dd04 ; CIA 2: Timer A, low byte. Used: read 1, written 1.
CI2TAHI                 = $dd05 ; CIA 2: Timer A, high byte. Used: read 1, written 1.
CI2TBLO                 = $dd06 ; CIA 2: Timer B, low byte. Used: read 1, written 1.
CI2TBHI                 = $dd07 ; CIA 2: Timer B, high byte. Used: read 1, written 1.
CI2ICR                  = $dd0d ; CIA 2: Interrupt control: read gives the sources and clears them; write sets (bit 7 = 1) or clears (bit 7 = 0) the enable bits. Its interrupt goes to the NMI line. Used: written 1.
CI2CRA                  = $dd0e ; CIA 2: Control A: start (bit 0), PB6 output (bit 1), toggle (bit 2), one-shot (bit 3), force load (bit 4), count CNT (bit 5), serial output (bit 6), TOD 50 Hz (bit 7). Used: written 1.
CI2CRB                  = $dd0f ; CIA 2: Control B: start (bit 0), PB7 output (bit 1), toggle (bit 2), one-shot (bit 3), force load (bit 4), input (bits 5-6), TOD alarm write (bit 7). Used: written 1.
